function valid(){if(state.step===0){const p=state.profile,n=state.profilePhase;return n===0?true:n===1?!!state.accountDraft?.name.trim():n===2?!!p.name.trim():n===3?(p.people.length>0||!!p.peopleOther.trim()):n===4?(p.categories.length>0||!!p.topicsOther.trim()):!!String(state.clubName||'').trim()}if(state.step===1&&editingId)return false;if(state.step===1)return state.selected.every(t=>(state.library[t]||[]).length>0&&(state.library[t]||[]).every(item=>item.title.trim()));if(state.step===2){if(state.phase===0)return !!(state.direction||state.description.trim());if(state.phase===1)return !!state.chosen;if(state.phase===2)return state.cycle!=='自定义'||(Number.isInteger(Number(state.customDays))&&Number(state.customDays)>=1&&Number(state.customDays)<=365);return !!(state.leader.name.trim()&&state.leader.bio.trim()&&state.leader.avatar)}if(state.step===3)return Number.isInteger(Number(state.ops.dailyCount))&&state.ops.dailyCount>=4&&state.ops.dailyCount<=20&&state.ops.formats.length>0;return true}
