function renderFeed(){document.body.dataset.setupView='feed';$('#action-dock').hidden=true;const count=Math.max(4,Math.min(20,Number(state.ops.dailyCount)||4)),formats=state.ops.formats;let pool=financeStories.filter(s=>formats.includes(s.format));if(!pool.length)pool=financeStories;const chosen=Array.from({length:count},(_,i)=>pool[i%pool.length]);renderNewspaperFeed(chosen,{count,formats,clubName:state.clubName,brief:state.feedBrief,editPreferences:()=>{state.step=3;render()}})}

function renderSummary(){const deferred=state.readingStatus!=='active';setQuestion('ISSUE NO.001 IS READY','你的读书会\n渐渐有了模样。',deferred?'“从读物出发，形成自己的判断，再与一群人分享。”\n主理人、书单和日常节奏都准备好了。第一期的想法也已保留，等你想开始时，再回来安排。':'“从读物出发，形成自己的判断，再与一群人分享。”\n主理人、书单、日常节奏和第一期共读，都已经记下。再看一眼，接下来就把这些想法交给阅读。');const identity=panel('读书会');identity.append(e('h2',state.clubName||'我的读书会'));if(state.clubNotes)identity.append(e('p',state.clubNotes));area.append(identity);const owner=panel('主理人');owner.append(e('h3',state.profile.name),e('p',profileBio()));const editOwner=e('button','修改主理人资料','chip');editOwner.onclick=()=>{state.step=0;state.profilePhase=0;render()};owner.append(editOwner);const resources=panel('书房与书单');resources.append(e('p',state.audience+' · '+state.domains.join(' / ')),e('p',state.selected.map(t=>t+' '+(state.library[t]?.length??state.counts[t])).join(' · ')));const r=e('button','修改资源与数量','chip');r.onclick=()=>{state.step=1;render()};resources.append(r);const ops=panel('日常的节奏');ops.append(e('p','每天 '+state.ops.dailyCount+' 份 · '+state.ops.formats.join('、')+' · '+state.ops.deliveryTime),e('p',state.ops.review));const b=e('button','修改运营策略','chip');b.onclick=()=>{state.step=3;render()};ops.append(b);const reading=panel('第一期共读',state.readingStatus==='later'?'晚点再说':state.readingStatus==='skipped'?'暂不创建':'已配置');if(!deferred&&state.chosen){reading.append(e('h2',state.chosen.title),e('p',state.chosen.type+' · '+state.chosen.author),e('p','方向：'+(state.description||state.direction)),e('p',readingLabel()+' · '+state.checkin));const img=e('img');img.src=state.leader.avatar;img.alt=state.leader.name+'的头像';img.className='leader-avatar';reading.append(img,e('h3',state.leader.name),e('p',state.leader.bio))}else reading.append(e('p',state.readingStatus==='later'?'已保留当前共读草稿，想开始时可以接着配置。':'先让日常阅读发生，共读活动可以以后再安排。'));const edit=e('button',deferred?(state.chosen?'继续配置共读':'创建一次共读'):'修改共读安排','chip');edit.onclick=()=>{state.step=2;if(!state.chosen)state.phase=0;render()};reading.append(edit);area.append(owner,resources,ops,reading);if(state.setupJob){const progress=panel();const view=e('button','查看初始化状态','chip');view.onclick=showSetupProgress;progress.append(view);area.append(progress)}}
function renderReadingDeferral(){const bar=e('div',null,'reading-deferral');bar.append(e('p','第一期不急着定。先把读书会准备好，刚才写下的都会留着。'));const later=e('button','晚点再说','text-button');later.onclick=()=>{record('第一期晚点再安排，先保留这些想法。');state.readingStatus='later';finishSetup()};bar.append(later);area.append(bar)}
let setupTimer=null;
function finishSetup(){state.step=4;state.setupJob={startedAt:Date.now(),status:'running'};render();showSetupProgress()}
function closeSetupProgress(dialog){clearInterval(setupTimer);if(window.initializeMotion)window.initializeMotion.closeDialog(dialog);else dialog.close()}
function showSetupProgress(){let dialog=$('#setup-progress');if(!dialog){dialog=e('dialog',null,'setup-progress-dialog');dialog.id='setup-progress';dialog.setAttribute('aria-labelledby','setup-progress-title');dialog.setAttribute('aria-describedby','setup-progress-description setup-initialization-note');const close=e('button',null,'setup-progress-close');close.type='button';close.setAttribute('aria-label','关闭初始化提示');const x=e('i',null,'font_family icon-Close');x.setAttribute('aria-hidden','true');close.append(x);close.onclick=()=>closeSetupProgress(dialog);const symbol=e('div',null,'setup-progress-symbol');symbol.append(e('i',null,'font_family icon-Check'));symbol.setAttribute('aria-hidden','true');const title=e('h2','正在为你的读书会，整理开篇……');title.id='setup-progress-title';const description=e('p','你关心的话题、选好的读物和运营安排，都记下了。接下来，从这些阅读线索里整理内容与观点。');description.id='setup-progress-description';const status=e('div',null,'setup-initialization-status');const dot=e('span',null,'setup-initialization-dot');dot.setAttribute('aria-hidden','true');const text=e('span');text.id='setup-initialization-status-text';status.append(dot,text);const note=e('p','整理预计需要数分钟至数小时，不必留在这里等待。你可以回到后台查看进展、编辑内容；完成后，系统会自动初始化用户端。这里仅演示流程，不会实际生成内容。','setup-initialization-note');note.id='setup-initialization-note';const done=e('button','我知道了','primary-button setup-progress-action');done.type='button';done.onclick=()=>closeSetupProgress(dialog);dialog.append(close,symbol,title,description,status,note,done);dialog.addEventListener('cancel',event=>{event.preventDefault();closeSetupProgress(dialog)});dialog.addEventListener('close',()=>{clearInterval(setupTimer);$('#question').focus({preventScroll:true})});document.body.append(dialog)}if(!dialog.open)dialog.showModal();window.initializeMotion?.openDialog(dialog);requestAnimationFrame(()=>dialog.querySelector('button').focus({preventScroll:true}));clearInterval(setupTimer);const statuses=['认识你','整理书房','挑选第一期','排好节奏'];let index=0;const update=()=>{dialog.querySelector('#setup-initialization-status-text').textContent=statuses[index];index=(index+1)%statuses.length};update();setupTimer=setInterval(update,2400)}

$('#next').onclick=()=>{if(!valid())return;if(state.step===0){if(state.profilePhase===2){record(profileReply());state.profilePhase=0}else if(state.profilePhase===0){if(accountStage()==='pending'){state.profilePhase=1;render();return}record(accountStage()==='confirmed'?'用已确认的资料继续。':'先不关联，我自己选几项。');state.profilePhase=3}else if(state.profilePhase===1){record(profileReply());confirmAccount()}else{record(profileReply());if(state.profilePhase===5){applyProfile();enterReadingShelf()}else{if(state.profilePhase===4&&!state.profile.topics.length)state.profile.topics=state.profile.categories.flatMap(c=>(topicGroups[c]||[c]).slice(0,1));state.profilePhase++}}render();return}if(state.step===1){record('先留下这些阅读来源：'+state.selected.map(t=>t+' '+state.library[t].length).join('、'));state.step=3;state.phase=0;render();return}else if(state.step===3){record('每天整理 '+state.ops.dailyCount+' 份'+state.ops.formats.join('、')+'内容，时间定在 '+state.ops.deliveryTime+'；'+(state.ops.autoPublish?'自动分享到读书会。':'由我确认后分享到读书会。'));state.step=5;state.readingStatus='pending';render();return}else if(state.step===2){if(state.phase===0){record(state.description||state.direction);state.chosen=null;state.batch=0;state.phase=1}else if(state.phase===1){record('选择《'+state.chosen.title+'》作为本次共读读物。');state.phase=2}else if(state.phase===2){record('阅读周期：'+readingLabel()+'；'+state.checkin);state.phase=3}else{record('由'+state.leader.name+'领读。'+state.leader.bio);state.readingStatus='active';finishSetup();return}}render()};
$('#back').onclick=()=>{if(state.step===0){if(state.profilePhase===0)state.profilePhase=2;else if(state.profilePhase===1)state.profilePhase=0;else if(state.profilePhase===3)state.profilePhase=profileAccounts().length?1:0;else if(state.profilePhase===4)state.profilePhase=3;else if(state.profilePhase===5)state.profilePhase=4}else if(state.step===1){state.step=0;state.profilePhase=5}else if(state.step===3){state.step=1;state.resourcePhase='review'}else if(state.step===2&&state.phase>0)state.phase--;else if(state.step===2)state.step=3;else if(state.step===4||state.step===5)state.step=3;render()};
$('#close-supplement').onclick=()=>{$('#describe-direction')?.setAttribute('aria-expanded','false');$('#next').disabled=!valid();const close=()=>{$('#supplement').hidden=true;document.body.classList.remove('composer-open');$('#describe-direction')?.setAttribute('aria-expanded','false');$('#next').disabled=!valid();$('#describe-direction')?.focus({preventScroll:true})};if(window.initializeMotion)window.initializeMotion.collapse($('#supplement'),close);else close()};
$('#supplement-form').onsubmit=event=>{event.preventDefault();const text=$('#supplement-input').value.trim();if(!text){feedback('留下一点想法吧。最近在意什么，或想一起聊什么，都可以。',true);return}state.description=text;state.directionDraft=text;record(text);state.chosen=null;state.batch=0;state.phase=1;render()};
$('#supplement-input').oninput=()=>{state.directionDraft=$('#supplement-input').value;$('#send-supplement').disabled=!state.directionDraft.trim();save()};
$('#supplement-input').onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();$('#supplement-form').requestSubmit()}};
if(feedStylePreview||new URLSearchParams(location.search).get('view')==='paper')state.step=5;render();if(saved?.version===2&&!feedStylePreview){const banner=$('#resume-banner');banner.hidden=false;banner.append(e('span','上次聊到一半的内容，都还在。'));const cont=e('button','接着上次继续');cont.onclick=()=>{banner.hidden=true;$('#current-message').scrollIntoView({block:'start'})};const restart=e('button','重新开始');restart.onclick=()=>{state=defaults();state.profileFlowVersion=3;state.accountDraft=null;state.accountBase=null;state.audiences=[];editingId=null;resourceSearch=null;undoBatch=null;undoResource=null;activeShelfType=null;listPages={};banner.hidden=true;render()};const actions=e('div',null,'resume-actions');actions.append(cont,restart);const dismiss=e('button',null,'resume-dismiss');dismiss.type='button';dismiss.setAttribute('aria-label','关闭恢复配置提示');dismiss.append(e('i',null,'font_family icon-Close'));dismiss.onclick=()=>{banner.hidden=true};banner.append(actions,dismiss)}
